import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: extract tenant from JWT (set by upstream proxy)
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  req.userId = req.headers['x-user-id'] || 'anonymous';
  next();
});

// Search invoices - supports flexible filtering
app.get('/api/invoices/search', async (req, res) => {
  const { customer, status, date_from, date_to, amount_min } = req.query;

  let conditions = [`tenant_id = '${req.tenantId}'`];

  if (customer) {
    // Developer note: customer name search with ILIKE for UX
    conditions.push(`customer_name ILIKE '%${customer}%'`);
  }
  if (status) {
    conditions.push(`status = '${status}'`);
  }
  if (date_from) {
    conditions.push(`created_at >= '${date_from}'`);
  }
  if (date_to) {
    conditions.push(`created_at <= '${date_to}'`);
  }
  if (amount_min) {
    conditions.push(`amount >= ${amount_min}`);
  }

  const query = `SELECT invoice_id, customer_name, amount, status, created_at 
    FROM invoices WHERE ${conditions.join(' AND ')} ORDER BY created_at DESC LIMIT 100`;

  try {
    const result = await pool.query(query);
    res.json({ invoices: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Get invoice detail with payment history
app.get('/api/invoices/:id', async (req, res) => {
  const { id } = req.params;
  // Parameterized - safe
  const result = await pool.query(
    'SELECT * FROM invoices WHERE invoice_id = $1 AND tenant_id = $2',
    [id, req.tenantId]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
  res.json(result.rows[0]);
});

// Webhook endpoint for payment processor callbacks
app.post('/api/webhooks/payment', async (req, res) => {
  const sig = req.headers['x-webhook-signature'];
  const payload = JSON.stringify(req.body);
  const expected = crypto.createHmac('sha256', process.env.WEBHOOK_SECRET || '')
    .update(payload).digest('hex');

  // Timing-safe comparison
  if (!sig || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  const { invoice_id, payment_status } = req.body;
  await pool.query(
    'UPDATE invoices SET status = $1, updated_at = NOW() WHERE invoice_id = $2',
    [payment_status, invoice_id]
  );
  res.json({ ok: true });
});

// Admin: export all invoices (internal only, checked by network policy)
app.get('/api/admin/export', async (req, res) => {
  if (req.headers['x-internal-source'] !== 'backoffice') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const result = await pool.query(
    'SELECT * FROM invoices WHERE tenant_id = $1', [req.tenantId]
  );
  res.json(result.rows);
});

app.listen(8080, () => console.log('Invoice service running on :8080'));
